    tags=['m_MT_FDI_RSTD_BOOKINGS_FQTR']
) }}
{{ config(materialized='table') }}
-- Self-referencing table(s): 'MT_FDI_RSTD_BOOKINGS_FQTR1' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
   DY.FISCAL_YEAR_QUARTER_NUMBER_INT AS FISCAL_YEAR_QUARTER_NUM_INT,
   PRODUCT_KEY,
   SALES_TERRITORY_KEY,
   SALES_REP_NUMBER AS SALES_REP_NUM,
   CANCELLED_FLG,
   ACQUISITION_FLG,
   CORPORATE_BOOKINGS_FLG,
   SERVICE_FLG,
   REVENUE_FLG,
   SUM(DD_COMP_US_NET_PRICE_AMOUNT) AS DD_COMP_US_NET_PRICE_AMT,
   SUM(DD_COMP_US_LIST_PRICE_AMOUNT) AS DD_COMP_US_LIST_PRICE_AMT,
   SUM(DD_COMP_US_COST_AMOUNT) AS DD_COMP_US_COST_AMT,
   SUM(DD_EXTENDED_QUANTITY) AS DD_EXTENDED_QTY,
   SUM(DD_COMP_US_HOLD_NET_PRICE_AMT) AS DD_COMP_US_HOLD_NET_PRICE_AMT,
   SUM(DD_COMP_US_HOLD_LIST_PRICE_AMT) AS DD_COMP_US_HOLD_LIST_PRICE_AMT,
   SUM(DD_COMP_US_HOLD_COST_AMOUNT) AS DD_COMP_US_HOLD_COST_AMT,
   SUM(DD_EXTENDED_HOLD_QUANTITY) AS DD_EXTENDED_HOLD_QTY,
   SUM(DD_COMP_US_STANDARD_PRICE_AMT) AS DD_COMP_US_STANDARD_PRICE_AMT,
   CAST('CORE' AS VARCHAR(50)) ACQUISITION_SOURCE_CD,
   CAST('CORE' AS VARCHAR(50)) DV_BOOKINGS_TYPE,
   DV_REVENUE_RECOGNITION_FLG,
   DV_NET_SPREAD_FLG,
   DV_ATTRIBUTION_CD,
   DV_PRODUCT_KEY,
   CURRENT_TIMESTAMP(0) AS EDW_CREATE_DTM,
   CURRENT_USER() AS EDW_CREATE_USER,
   CURRENT_TIMESTAMP(0) AS EDW_UPDATE_DTM,
   CURRENT_USER() AS EDW_UPDATE_USER,
   DV_FMV_FLG
FROM
   {{ var('m_MT_FDI_RSTD_BOOKINGS_FQTR_SLSORDVWDB') }}.MT_RSTD_BKGS_MEASURE BKGS,
   {{ var('m_MT_FDI_RSTD_BOOKINGS_FQTR_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR DY
WHERE
   BKGS.BOOKINGS_PROCESS_DATE = DY.CALENDAR_DATE
   AND DY.FISCAL_YEAR_AGE BETWEEN 0 AND 2
   AND COLLATE(DV_REVENUE_RECOGNITION_FLG, 'en-ci-rtrim') = 'Y'
GROUP BY
   DY.FISCAL_YEAR_QUARTER_NUMBER_INT,
   PRODUCT_KEY,
   SALES_TERRITORY_KEY,
   SALES_REP_NUMBER,
   CANCELLED_FLG,
   ACQUISITION_FLG,
   CORPORATE_BOOKINGS_FLG,
   SERVICE_FLG,
   REVENUE_FLG,
   DV_REVENUE_RECOGNITION_FLG,
   DV_NET_SPREAD_FLG,
   DV_ATTRIBUTION_CD,
   DV_PRODUCT_KEY,
   DV_FMV_FLG
UNION ALL
SELECT
   DY.FISCAL_YEAR_QUARTER_NUMBER_INT AS FISCAL_YEAR_QUARTER_NUM_INT,
   CISCO_PRODUCT_KEY PRODUCT_KEY,
   SALES_TERRITORY_KEY,
   SALES_REP_NUMBER AS SALES_REP_NUM,
   '=' CANCELLED_FLG,
   '=' ACQUISITION_FLG,
   CORPORATE_BOOKINGS_FLG,
   SERVICE_FLG,
   '=' REVENUE_FLG,
   SUM(EXTENDED_SELLING_PRICE_USD_AMT) AS DD_COMP_US_NET_PRICE_AMT,
   0.000000 AS DD_COMP_US_LIST_PRICE_AMT,
   SUM(EXTENDED_STANDARD_COST_USD_AMT) AS DD_COMP_US_COST_AMT,
   SUM(ORDER_QTY) AS DD_EXTENDED_QTY,
   0.000000 DD_COMP_US_HOLD_NET_PRICE_AMT,
   0.000000 DD_COMP_US_HOLD_LIST_PRICE_AMT,
   0.000000 AS DD_COMP_US_HOLD_COST_AMT,
   0.000000 AS DD_EXTENDED_HOLD_QTY,
   0.000000 DD_COMP_US_STANDARD_PRICE_AMT,
   ACQUISITION_SOURCE_CD ACQUISITION_SOURCE_CD,
   'NON-CORE' DV_BOOKINGS_TYPE,
   'Y' DV_REVENUE_RECOGNITION_FLG,
   'N' DV_NET_SPREAD_FLG,
   'STANDALONE' DV_ATTRIBUTION_CD,
   CISCO_PRODUCT_KEY DV_PRODUCT_KEY,
   CURRENT_TIMESTAMP(0) AS EDW_CREATE_DTM,
   CURRENT_USER() AS EDW_CREATE_USER,
   CURRENT_TIMESTAMP(0) AS EDW_UPDATE_DTM,
   CURRENT_USER() AS EDW_UPDATE_USER,
   'N' DV_FMV_FLG
FROM
   {{ var('m_MT_FDI_RSTD_BOOKINGS_FQTR_SLSORDVWDB') }}.N_APSP_FDI_BOOKINGS_TRX FDI,
   {{ var('m_MT_FDI_RSTD_BOOKINGS_FQTR_COMREFVWDB') }}.R_FISCAL_MONTH_TO_YEAR DY
WHERE
   FDI.FISCAL_YEAR_MONTH_INT = DY.FISCAL_YEAR_MONTH_INT
   AND DY.FISCAL_YEAR_AGE BETWEEN 0 AND 2
GROUP BY
   DY.FISCAL_YEAR_QUARTER_NUMBER_INT,
   CISCO_PRODUCT_KEY,
   SALES_TERRITORY_KEY,
   SALES_REP_NUMBER,
   CORPORATE_BOOKINGS_FLG,
   SERVICE_FLG,
   ACQUISITION_SOURCE_CD